static void Gate(bool ok,const char* reason){if(!ok)throw std::runtime_error(reason);}
struct CoverageWriterLock {
 HANDLE handle=nullptr;
 explicit CoverageWriterLock(const fs::path& root){auto text=fs::canonical(root).generic_string();auto hash=Hash(std::vector<unsigned char>(text.begin(),text.end()));std::wstring name=L"Local\\Atlas2.Coverage."+std::wstring(hash.begin(),hash.end());handle=CreateMutexW(nullptr,FALSE,name.c_str());Gate(handle!=nullptr,"coverage writer mutex unavailable");DWORD state=WaitForSingleObject(handle,0);if(state!=WAIT_OBJECT_0&&state!=WAIT_ABANDONED){CloseHandle(handle);handle=nullptr;Gate(false,"another coverage writer is active");}}
 ~CoverageWriterLock(){if(handle){ReleaseMutex(handle);CloseHandle(handle);}}
};
static void AtomicBytes(const fs::path& path,const std::vector<unsigned char>& data){
 Gate(fs::space(path.parent_path()).available>=16ull*1024*1024*1024+data.size()+32ull*1024*1024,"free-space reserve before coverage metadata write");
 auto tmp=path;tmp+=".coverage-tmp";Write(tmp,data);auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);
 for(;;){BOOL done=fs::exists(path)?ReplaceFileW(path.c_str(),tmp.c_str(),nullptr,0,nullptr,nullptr):MoveFileExW(tmp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);if(done)return;DWORD error=GetLastError();if((error!=5&&error!=32&&error!=33)||std::chrono::steady_clock::now()>=deadline)throw std::runtime_error("coverage atomic replacement blocked");std::this_thread::sleep_for(std::chrono::milliseconds(50));}
}
static void AtomicJson(const fs::path& path,const Json& json){auto s=json.dump();AtomicBytes(path,{s.begin(),s.end()});}
static std::string Id(int layer){auto value=std::to_string(layer);return "F"+std::string(3-value.size(),'0')+value;}
static Json Detail(const fs::path& area,const Json& header){auto bytes=Read(area/header.at("view_file").get<std::string>(),16*1024*1024);Gate(Hash(bytes)==header.at("view_sha256").get<std::string>(),"source view identity");return Json::parse(bytes);}
static std::vector<TileTable> Tables(const Json& view){std::vector<TileTable> tables;for(const auto& group:view.at("groups")){TileTable table;for(const auto& t:view.at("tile_sets").at(group.at("tile_set").get<int>()))Gate(table.emplace(Key{t.at(0),t.at(1),t.at(2)},t.at(3).get<std::string>()).second,"duplicate source tile");tables.push_back(std::move(table));}return tables;}
static void Compact(Json& view,const std::vector<TileTable>& tables){Json sets=Json::array();std::map<std::string,int> shared;for(size_t gi=0;gi<tables.size();++gi){Json records=Json::array();for(const auto&[key,hash]:tables[gi])records.push_back({std::get<0>(key),std::get<1>(key),std::get<2>(key),hash});std::string text=records.dump(),hash=Hash({text.begin(),text.end()});auto it=shared.find(hash);int set;if(it==shared.end()){set=int(sets.size());shared.emplace(hash,set);sets.push_back(std::move(records));}else set=it->second;view["groups"][gi]["tile_set"]=set;}view["tile_sets"]=std::move(sets);}
static std::array<int,4> Range(const Primitive& p,const Transform& transform,int level){double factor=std::ldexp(1.,-level),x0=INFINITY,y0=INFINITY,x1=-INFINITY,y1=-INFINITY;for(int k=0;k<(p.stroke?2:3);++k){auto v=transform.Image(p.v[k*2],p.v[k*2+1]);x0=std::min(x0,v[0]*factor);y0=std::min(y0,v[1]*factor);x1=std::max(x1,v[0]*factor);y1=std::max(y1,v[1]*factor);}double pad=Gutter+1+(p.stroke?p.width*transform.ppu*factor*.5:0);int nx=int(std::ceil(transform.width*factor/Tile)),ny=int(std::ceil(transform.height*factor/Tile));return {std::max(0,int(std::floor((x0-pad)/Tile))),std::max(0,int(std::floor((y0-pad)/Tile))),std::min(nx-1,int(std::floor((x1+pad)/Tile))),std::min(ny-1,int(std::floor((y1+pad)/Tile)))};}
int RepairCoverage(int argc,char**argv){try{
 Gate(argc==6,"usage repair-coverage pack-root assets inventory report stage-id");fs::path root=fs::canonical(argv[1]),assets=fs::absolute(argv[2]),inventory_path=fs::absolute(argv[3]);CoverageWriterLock writer(root);std::string stage=argv[5];Gate(stage.size()==64&&stage.find_first_not_of("0123456789abcdef")==std::string::npos,"stage content identity");auto index_bytes=Read(root/"atlas2-index.json"),inventory_bytes=Read(inventory_path);Json index=Json::parse(index_bytes),inventory=Json::parse(inventory_bytes);bool trial=fs::exists(root/"coverage-trial.json");
 Gate(inventory.at("structural_pass")==true,"structural validation required before raster repair");if(!trial){auto state=ReadJson(root/"generation-state.json");Gate(state.at("state")=="complete"&&state.at("complete_views")==602&&inventory.at("improved_views")==602&&inventory.at("areas")==16,"complete base generation/inventory required");}
 std::map<std::string,std::vector<Json>> targets;for(const auto& gap:inventory.at("raster_gaps"))targets[gap.at("area").get<std::string>()].push_back(gap);Gate(targets.size()<=16,"area repair bound");auto index_backup=root/("atlas2-index-pre-coverage-"+stage.substr(0,12)+".json");Json outcomes=Json::array();
 for(auto& entry:index["areas"]){std::string label=entry.at("area");if(!targets.contains(label))continue;fs::path area=root/label;auto old_manifest=Read(area/"manifest.json");Gate(Hash(old_manifest)==entry.at("manifest_sha256").get<std::string>(),"area manifest identity");Json manifest=Json::parse(old_manifest),source=ReadJson(assets/"maps"/(entry.at("region_id").get<std::string>()+".json")),features=ReadJson(assets/"maps/features.json");Gate(Hash(Read(assets/"maps"/(entry.at("region_id").get<std::string>()+".json")))==manifest.at("source_sha256").get<std::string>(),"repair geometry identity");Gate(manifest.at("schema")==3,"external composite schema required");for(const auto& h:manifest.at("views"))Gate(h.contains("view_file"),"complete selected area required");std::set<Geometry> geometry;
  for(const auto& old:manifest.value("coverage_geometry",Json::array()))geometry.insert(old.get<Geometry>());
  auto bounds=manifest.at("bounds").get<std::array<double,4>>();Raster check;check.transform={bounds[0],bounds[3],16,int(std::ceil((bounds[2]-bounds[0])*16)),int(std::ceil((bounds[3]-bounds[1])*16))};
  for(const auto& gap:targets[label]){int layer=std::stoi(gap.at("layer_id").get<std::string>().substr(1)),triangle=gap.at("triangle_index");Gate(layer>=0&&layer<int(source["layers"].size()),"counterexample layer");const auto& triangles=source["layers"][layer]["triangles"];Gate(triangle>=0&&triangle<int(triangles.size()),"counterexample triangle");Geometry v=triangles[triangle].get<Geometry>();Gate(v==gap.at("triangle_xz").get<Geometry>(),"counterexample source identity");Primitive p;p.v=v;double altitude=Atlas2Coverage::MinimumAltitude(check,p);Gate(altitude>0&&altitude<1,"counterexample is not a nondegenerate subpixel triangle");geometry.insert(v);}
  Json geometry_json=Json::array();for(const auto& g:geometry)geometry_json.push_back(g);std::string geometry_text=geometry_json.dump(),geometry_hash=Hash({geometry_text.begin(),geometry_text.end()});
  if(manifest.value("coverage_stage_id",std::string())==stage&&manifest.value("coverage_geometry_sha256",std::string())==geometry_hash){outcomes.push_back({{"area",label},{"already_complete",true}});continue;}
  Gate(Hash(Read(assets/"maps/features.json"))==manifest.at("feature_sha256").get<std::string>(),"repair reveal-feature identity");uint64_t bytes=0;for(const auto& f:fs::recursive_directory_iterator(root))if(f.is_regular_file())bytes+=f.file_size();uint64_t metadata_reserve=uint64_t(manifest["views"].size())*16*1024*1024+128ull*1024*1024;Gate(bytes+metadata_reserve<16ull*1024*1024*1024,"full output budget before coverage stage");if(!fs::exists(index_backup))AtomicBytes(index_backup,index_bytes);_putenv_s("BB_ATLAS2_BAKE_REMAINING_BYTES",std::to_string(16ull*1024*1024*1024-bytes-metadata_reserve).c_str());Baker baker(area,source,features.at("areas").at(entry.at("region_id").get<std::string>()),assets/"art",16);size_t changed_views=0,changed_records=0,rendered_variants=0;
  for(int layer=0;layer<int(manifest["views"].size());++layer){auto& header=manifest["views"][layer];Json view=Detail(area,header);Gate(view.at("layer_index")==layer&&view.at("generator_identity")==manifest.at("parity_generator_identity"),"base view identity");auto tables=Tables(view);size_t before=changed_records;
   for(int level=0;level<view.at("levels").get<int>();++level){std::set<Coordinate> selected;for(const auto& v:geometry){Primitive p;p.v=v;auto range=Range(p,baker.transform,level);for(int x=range[0];x<=range[2];++x)for(int y=range[1];y<=range[3];++y)selected.insert({x,y});}Gate(selected.size()<=4096,"coverage tile selection bound");
    for(int shaded=0;shaded<2;++shaded){auto primitives=baker.Primitives(layer,level,shaded!=0);std::map<Coordinate,std::vector<size_t>> buckets;for(auto tile:selected)buckets[tile];for(size_t i=0;i<primitives.size();++i){auto range=Range(primitives[i],baker.transform,level);for(auto&[tile,ids]:buckets)if(tile.first>=range[0]&&tile.first<=range[2]&&tile.second>=range[1]&&tile.second<=range[3])ids.push_back(i);}
     for(const auto&[tile,ids]:buckets){std::map<std::vector<size_t>,std::string> reused;for(size_t gi=0;gi<tables.size();++gi){const auto& group=view["groups"][gi];if(group.at("shaded")!=shaded)continue;int mask=-1;if(group.at("fog_mode")=="on"){mask=0;for(int bit:group.at("requires"))mask|=1<<bit;}std::vector<size_t> visible;for(size_t id:ids)if(Visible(primitives[id].required,mask))visible.push_back(id);std::string hash;auto found=reused.find(visible);
       if(found!=reused.end())hash=found->second;else{if(!visible.empty()){Raster raster;raster.transform=baker.transform;raster.level=level;raster.tx=tile.first;raster.ty=tile.second;raster.texture=&baker.parchment;raster.material_x=float((bounds[0]+bounds[2])*.5);raster.material_z=float((bounds[1]+bounds[3])*.5);raster.material_span=float(std::max(bounds[2]-bounds[0],bounds[3]-bounds[1]));for(size_t id:visible){const auto& primitive=primitives[id];if(primitive.textured&&geometry.contains(primitive.v))Atlas2Coverage::DrawTriangle(raster,primitive);else raster.Draw(primitive);}bool occupied=false;for(size_t at=3;at<raster.pixels.size();at+=4)if(raster.pixels[at]){occupied=true;break;}if(occupied)hash=fs::path(baker.Store(raster.pixels)).stem().string();++rendered_variants;}reused.emplace(std::move(visible),hash);}
       Key key{level,tile.first,tile.second};auto old=tables[gi].find(key);if(hash.empty()){if(old!=tables[gi].end()){tables[gi].erase(old);++changed_records;}}else if(old==tables[gi].end()||old->second!=hash){tables[gi][key]=hash;++changed_records;}
     }}
    }
   }
   if(changed_records!=before){Compact(view,tables);view["coverage_postprocess"]={{"schema",1},{"id",stage},{"geometry_sha256",geometry_hash},{"method","analytic pixel area for inventoried subpixel floor triangles"}};Gate(view.dump().size()<=16*1024*1024,"coverage view runtime bound");std::string name="views/"+Id(layer)+"-coverage-"+stage.substr(0,12)+".json";AtomicJson(area/name,view);header["view_file"]=name;header["view_sha256"]=Hash(Read(area/name,16*1024*1024));++changed_views;}std::cout<<"COVERAGE_VIEW "<<label<<" "<<Id(layer)<<" changed_views="<<changed_views<<"\n"<<std::flush;
  }
  auto backup=area/("manifest-pre-coverage-"+stage.substr(0,12)+".json");if(!fs::exists(backup))AtomicBytes(backup,old_manifest);manifest["coverage_geometry"]=geometry_json;manifest["coverage_geometry_sha256"]=geometry_hash;manifest["coverage_stage_id"]=stage;Json outcome={{"area",label},{"geometry_count",geometry.size()},{"changed_views",changed_views},{"changed_tile_records",changed_records},{"rendered_variants",rendered_variants},{"new_objects",baker.new_objects},{"new_object_bytes",baker.new_bytes},{"base_generator_identity",manifest["parity_generator_identity"]},{"stage_id",stage},{"inventory_sha256",Hash(inventory_bytes)}};manifest["coverage_postprocess_history"].push_back(outcome);Gate(manifest.dump().size()<=32*1024*1024,"coverage manifest runtime bound");AtomicJson(area/"manifest.json",manifest);entry["manifest_sha256"]=Hash(Read(area/"manifest.json"));Gate(index.dump().size()<=1024*1024,"coverage index runtime bound");AtomicJson(root/"atlas2-index.json",index);outcomes.push_back(outcome);AtomicJson(argv[4],{{"schema",1},{"complete",false},{"trial",trial},{"results",outcomes},{"raster_validation_required",true}});std::cout<<"COVERAGE_AREA_READY "<<label<<" views="<<changed_views<<" bytes="<<baker.new_bytes<<"\n"<<std::flush;
 }
 AtomicJson(argv[4],{{"schema",1},{"complete",true},{"trial",trial},{"stage_id",stage},{"input_inventory_sha256",Hash(inventory_bytes)},{"index_sha256",Hash(Read(root/"atlas2-index.json"))},{"results",outcomes},{"base_generator_unchanged",true},{"raster_validation_required",true},{"native_gameplay_tested",false}});std::cout<<"COVERAGE_STAGE_COMPLETE areas="<<outcomes.size()<<"\n";return 0;
}catch(const std::exception& e){std::cout<<"COVERAGE_STAGE_BLOCKED "<<e.what()<<"\n";return 1;}}
